import { BlurVignette, BlurVignetteArticle } from '@/registry/ui-layouts/blur-vignette';
import React from 'react';

const cards = [
  {
    src: 'https://img.freepik.com/free-photo/cartoon-superhero-illustration_23-2151732547.jpg',
    title: 'Night Watch',
    body: 'A comic-panel hero over a city skyline. The caption sits on a frosted strip that melts into the art instead of covering it.',
  },
  {
    src: 'https://img.freepik.com/free-photo/halloween-scene-illustration-anime-style_23-2151794328.jpg',
    title: 'Pumpkin Rooftop',
    body: 'Moonlight, a rooftop and one very patient pumpkin. Hover to slide the blurred caption up over the scene.',
  },
];

function Blurvignettecard() {
  return (
    <div className='mx-auto w-fit gap-4 sm:flex justify-center md:p-8 sm:p-4'>
      {cards.map((c) => (
        <BlurVignette
          key={c.title}
          classname='group w-80 shrink-0'
          radius='15px'
          inset='100px'
          transitionLength='200px'
          blur='15px'
        >
          <img
            src={c.src}
            alt={c.title}
            width={600}
            height={600}
            className='relative mx-auto h-full w-full object-cover transition-transform duration-700 group-hover:scale-105'
          />
          <BlurVignetteArticle classname='bottom-1 left-2 h-[38%] w-[96%] translate-y-[55%] rounded-xl border border-neutral-900/20 text-white transition-transform duration-500 ease-out group-hover:translate-y-0'>
            <article className='px-3 py-5'>
              <h1 className='text-2xl font-semibold'>{c.title}</h1>
              <p className='mt-1 text-xs text-white/85 opacity-0 transition-opacity delay-100 duration-500 group-hover:opacity-100'>
                {c.body}
              </p>
            </article>
          </BlurVignetteArticle>
        </BlurVignette>
      ))}
    </div>
  );
}

export default Blurvignettecard;

'use client';
import { cn } from '@/lib/utils';
import type React from 'react';
import { createContext, useContext } from 'react';

interface BlurVignetteContextProps {
  radius?: string;
  inset?: string;
  transitionLength?: string;
  blur?: string;
}

const BlurVignetteContext = createContext<BlurVignetteContextProps>({
  radius: '24px',
  inset: '20px',
  transitionLength: '44px',
  blur: '6px',
});

// Self-contained styles for the vignette layer (no global CSS needed)
const BLUR_VIGNETTE_CSS = `.blur-vignette{position:absolute;-webkit-backdrop-filter:blur(var(--blur));backdrop-filter:blur(var(--blur));--r:max(var(--transition-length),calc(var(--radius) - var(--inset)));--corner-size:calc(var(--r) + var(--inset)) calc(var(--r) + var(--inset));--corner-gradient:transparent 0px,transparent calc(var(--r) - var(--transition-length)),black var(--r);--fill-gradient:black,black var(--inset),transparent calc(var(--inset) + var(--transition-length)),transparent calc(100% - var(--transition-length) - var(--inset)),black calc(100% - var(--inset));--fill-narrow-size:calc(100% - (var(--inset) + var(--r)) * 2);--fill-farther-position:calc(var(--inset) + var(--r));-webkit-mask-image:linear-gradient(to right,var(--fill-gradient)),linear-gradient(to bottom,var(--fill-gradient)),radial-gradient(at bottom right,var(--corner-gradient)),radial-gradient(at bottom left,var(--corner-gradient)),radial-gradient(at top left,var(--corner-gradient)),radial-gradient(at top right,var(--corner-gradient));mask-image:linear-gradient(to right,var(--fill-gradient)),linear-gradient(to bottom,var(--fill-gradient)),radial-gradient(at bottom right,var(--corner-gradient)),radial-gradient(at bottom left,var(--corner-gradient)),radial-gradient(at top left,var(--corner-gradient)),radial-gradient(at top right,var(--corner-gradient));-webkit-mask-size:100% var(--fill-narrow-size),var(--fill-narrow-size) 100%,var(--corner-size),var(--corner-size),var(--corner-size),var(--corner-size);mask-size:100% var(--fill-narrow-size),var(--fill-narrow-size) 100%,var(--corner-size),var(--corner-size),var(--corner-size),var(--corner-size);-webkit-mask-position:0 var(--fill-farther-position),var(--fill-farther-position) 0,0 0,100% 0,100% 100%,0 100%;mask-position:0 var(--fill-farther-position),var(--fill-farther-position) 0,0 0,100% 0,100% 100%,0 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat}`;

export const useBlurVignetteContext = () => useContext(BlurVignetteContext);

interface BlurVignetteProps {
  classname?: string;
  children: React.ReactNode;
  radius?: string;
  inset?: string;
  transitionLength?: string;
  blur?: string;
  blurclassname?: string;
}

export const BlurVignette: React.FC<BlurVignetteProps> = ({
  classname,
  children,
  radius = '24px',
  inset = '20px',
  transitionLength = '44px',
  blur = '6px',
}) => {
  return (
    <BlurVignetteContext.Provider value={{ radius, inset, transitionLength, blur }}>
      <div
        className={cn('relative aspect-square overflow-hidden', classname)}
        style={{ borderRadius: radius }}
      >
        <style>{BLUR_VIGNETTE_CSS}</style>
        {children}
      </div>
    </BlurVignetteContext.Provider>
  );
};
interface BlurVignetteArticleProps {
  children?: React.ReactNode;
  classname?: string;
}

export const BlurVignetteArticle: React.FC<BlurVignetteArticleProps> = ({
  children,
  classname,
}) => {
  const { radius, inset, transitionLength, blur } = useBlurVignetteContext();

  return (
    <div
      className={cn('blur-vignette bottom-0 left-0 w-full h-full z-1', classname)}
      style={
        {
          '--radius': radius,
          '--inset': inset,
          '--transition-length': transitionLength,
          '--blur': blur,
        } as React.CSSProperties
      }
    >
      {children}
    </div>
  );
};
